"""Writes docs/data_quality_record.md from the computed trip table (numbers are never typed by hand)."""
from . import config


def write_dq_record(df, rs):
    tr, st = df[df.partition == "train"], df[df.partition == "student_test"]
    bad = df[~df.trip_ok]
    r75 = rs.iloc[(rs.radius_m - config.CAND_RADIUS_M).abs().argmin()]
    lines = [
        "# Data-quality record (auto-generated by `python -m pathsnap.cli explore`)", "",
        f"Partitions analysed: train = {len(tr)} trips, student_test = {len(st)} trips. Evaluator-test data is NOT present and was never used.", "",
        "## Issues, assumptions and decisions", "",
        "| # | Observation (measured) | Decision / assumption |", "|---|---|---|",
        f"| 1 | Sampling is nominally 1 Hz: {100*(df.dt_eq_1s_frac*(df.n_points-1)).sum()/(df.n_points-1).sum():.1f}% of all steps are exactly 1 s (pooled; per-trip median {100*df.dt_eq_1s_frac.median():.1f}%, worst trip {100*df.dt_eq_1s_frac.min():.0f}%); {int(df.gaps_gt_5s.sum())} gaps >5 s and {int(df.gaps_gt_30s.sum())} gaps >30 s in total; the two largest gaps are {', '.join(f'{r.dt_max_s:.0f} s in trip {r.trip_id}' for r in df.nlargest(2,'dt_max_s').itertuples())} (recording paused). | Time-gap features (`dt_prev`, `dt_next`); neighbour/window features ignore neighbours >10 s away; speed uses only valid neighbours. |",
        f"| 2 | Missing values: {int(df.nan_values_track.sum() + df.nan_values_net.sum())} NaN cells; invalid (0,0/out-of-range) coordinates: {int(df.invalid_coords.sum())}; duplicate timestamps: {int(df.dup_timestamps.sum())}; timestamps going backwards: {int(df.time_going_backwards.sum())}. | No imputation needed for raw files. Rows are kept in time order. |",
        f"| 3 | Implausible speeds (>60 m/s) occur in {int((df.speed_gt_60mps>0).sum())} trips ({int(df.speed_gt_60mps.sum())} steps) - GPS jumps. | Not deleted (the model must cope with noise at test time); jumps are captured by window features. |",
        f"| 4 | Coordinates are lon/lat degrees and trips are in many cities ({df.utm_epsg.nunique()} UTM zones). | Each trip is projected to the UTM zone of its own centroid; all distances in metres. |",
        f"| 5 | Road networks are directed: {100*df.two_way_arc_frac.mean():.0f}% of arcs have a reverse arc (two-way roads). Both directions of one road lie at the same distance from a GPS point. | Direction features (`heading_diff_deg`, `cos_heading`, `along_advance_m`, `has_reverse`) separate them. |",
        f"| 6 | Connectivity: median largest-component share = {100*df.largest_comp_frac.median():.1f}% of nodes; {int((df.n_components>1).sum())} of {len(df)} networks have >1 weakly-connected component; isolated nodes total = {int(df.isolated_nodes.sum())}. | Disconnected parts exist; transitions between disconnected arcs are handled by the HMM (Person 3). |",
        f"| 7 | Reference route: {int(df.route_breaks.sum())} breaks (end node of arc i != start node of arc i+1) over {len(df)} trips; {int((df.route_revisits>0).sum())} trips revisit an arc. | Treated as reference, not perfect truth. Breaks are not repaired. |",
        f"| 8 | `.route` has far fewer rows than the track ({int(df.n_route_arcs.median())} route arcs vs {int(df.n_points.median())} GPS points, medians): it is a list of ARCS, not one label per point. | Point labels are derived by a monotone dynamic-programming alignment (`labels.py`). |",
        f"| 9 | Reference route covers only part of the GPS trace in {len(bad)} trip(s): " + ", ".join(f"{r.trip_id} (route/path = {r.route_over_path:.2f}, {100*r.frac_label_invalid:.0f}% of points >{config.LABEL_MAX_DIST_M:.0f} m from reference)" for r in bad.itertuples()) + ". | Flagged `trip_ok = False`, excluded from training/CV/optimisation (fold = -1); still listed in the inventory. |",
        f"| 10 | Points >{config.LABEL_MAX_DIST_M:.0f} m from the aligned reference arc in otherwise-good trips: {100*(df[df.trip_ok].frac_label_invalid*df[df.trip_ok].n_points).sum()/df[df.trip_ok].n_points.sum():.2f}% of points. | `label_valid = False` for these points; not used as training/validation labels (the reference does not cover them). |",
        f"| 11 | Candidate radius {config.CAND_RADIUS_M:.0f} m gives candidate-miss-rate {100*r75.candidate_miss_rate:.2f}% over ALL points of reliable train trips ({100*r75.miss_rate_valid_labels_only:.2f}% over valid-label points, which is ~0 by construction) with {r75.avg_candidates_per_point:.1f} candidates/point (see radius_study.csv). | Fixed radius {config.CAND_RADIUS_M:.0f} m, max {config.MAX_CANDIDATES} nearest candidates. |",
        "", "## Label definition (important for the viva)", "",
        "For each GPS point the label arc is the reference-route arc it was aligned to (monotone DP minimising point-to-arc distance, capped at 150 m). "
        "A candidate row has `label = 1` iff its arc equals that arc. This is a *derived* label; its limitations are the items 8-10 above.",
        "", "## Leakage controls", "",
        "- Feature code (`features.py`) never reads `.route`; `load_trip(with_route=False)` is the inference path.",
        "- Folds are by trip (GroupKFold style), so no trip's points are split across train/validation.",
        "- Only train + student_test were read; no learned preprocessing exists (features are deterministic functions of geometry), so nothing is fitted on test data.",
    ]
    p = config.ROOT / "docs" / "data_quality_record.md"; p.parent.mkdir(exist_ok=True); p.write_text("\n".join(lines) + "\n")
